 "content": "def transform(grid):
    """Mirror the grid horizontally and tile three vertical bands, alternating vertical orientation."""
    h = len(grid)
    if h == 0:
        return []
    bands = [grid[::-1], grid, grid[::-1]]
    out = []
    for band in bands:
        for row in band:
            out.append(list(reversed(row)) + list(row))
    return out
